  cy.get('.flatpickr-day:visible:nth(25)').click('bottom', { force: true });
  cy.get(`[style="top:${GRID_ROW_HEIGHT * 2}px"] > .slick-cell:nth(6)`).should('contain', '2009-01-22');

  // change City of Origin
